package io.forgeloop.control.integrations.github;
import java.nio.charset.StandardCharsets; import java.security.*; import java.util.HexFormat; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.stereotype.Component;
@Component public class GithubWebhookVerifier { public boolean valid(String secret,String signature,String body){if(secret==null||secret.isBlank()||signature==null||!signature.startsWith("sha256="))return false;try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String expected="sha256="+HexFormat.of().formatHex(mac.doFinal(body.getBytes(StandardCharsets.UTF_8)));return MessageDigest.isEqual(expected.getBytes(StandardCharsets.US_ASCII),signature.getBytes(StandardCharsets.US_ASCII));}catch(GeneralSecurityException ex){throw new IllegalStateException("HMAC unavailable",ex);}} }
